{"kind":"source-patchset","version":1,"disposition":"candidate","reason":"Corrects the public B2a findings for date admission, exact JSONL measurement, causal ordering over the required cause graph, and malformed Unicode feed arguments. Preserves host functions, source discovery and reconstruction, and all three explicit effect incompleteness boundaries. This remains a read-scope stage and makes no acceptance claim.","changes":[{"operation":"edit","path":"src/journal/filesystem/source-owner.mjs","inputSha256":"dc41ed2901dc357e62978b05f633a901be05d6bb4bc5d563ff0cda76b017ecb8","replacements":[{"before":"function scopeFeed(value) {
  if (!safeSourceFeed(value)) throw new TypeError("journal feed is invalid");
  return value;
}","after":"function scopeFeed(value) {
  if (!safeSourceFeed(value)) throw new TypeError("journal feed is invalid");
  for (let index = 0; index < value.length; index += 1) {
    const unit = value.charCodeAt(index);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) throw new TypeError("journal feed is invalid");
      index += 1;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      throw new TypeError("journal feed is invalid");
    }
  }
  return value;
}"},{"before":"function scopeDate(value) {
  if (typeof value !== "string" || !/^\\d{4}-\\d{2}-\\d{2}$/u.test(value)) {
    throw new TypeError("journal date is invalid");
  }
  return value;
}","after":"function scopeDate(value) {
  if (typeof value !== "string" || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/u.test(value)) {
    throw new TypeError("journal date is invalid");
  }
  return value;
}"},{"before":"function sourceOrderedEnvelopes(view, refs) {
  const witnesses = [];
  for (const ref of refs) {
    const witness = view.substrate.witness(ref);
    if (witness === undefined) throw unavailable("evidence-unavailable", "selected-witness-missing");
    witnesses.push(witness);
  }
  let ordered;
  try { ordered = topologicalOrder(causalGraphOf(witnesses)); }
  catch (error) { throw unavailable("source-corrupt", "selected-causal-order", error); }
  return Object.freeze(ordered.map((witness) => {
    const envelope = view.envelopes.get(witness.id);
    if (envelope === undefined) throw unavailable("evidence-unavailable", "selected-envelope-missing");
    return envelope.statement;
  }));
}","after":"function sourceOrderedEnvelopes(view, refs, requiredRefs = refs) {
  const selected = new Set(refs);
  const closure = new Set();
  const pending = [...requiredRefs];
  const witnesses = [];
  while (pending.length > 0) {
    const ref = pending.pop();
    if (closure.has(ref)) continue;
    const witness = view.substrate.witness(ref);
    if (witness === undefined) throw unavailable("evidence-unavailable", "selected-cause-missing");
    if (view.substrate.witnessState(ref) !== "admitted") {
      throw unavailable("evidence-unavailable", "selected-cause-incomplete");
    }
    closure.add(ref);
    witnesses.push({ id: ref, core: witness.core });
    for (const cause of witness.core.causes) pending.push(cause);
  }
  let ordered;
  try { ordered = topologicalOrder(causalGraphOf(witnesses)); }
  catch (error) { throw unavailable("source-corrupt", "selected-causal-order", error); }
  const result = [];
  for (const witness of ordered) {
    if (!selected.has(witness.id)) continue;
    const envelope = view.envelopes.get(witness.id);
    if (envelope === undefined) throw unavailable("evidence-unavailable", "selected-envelope-missing");
    result.push(envelope.statement);
  }
  return Object.freeze(result);
}"},{"before":"function sourceAsOfRefs(view, selection) {
  const closure = new Set();
  const pending = [...selection.frontier];
  while (pending.length > 0) {
    const ref = pending.pop();
    if (closure.has(ref)) continue;
    if (view.substrate.witnessState(ref) !== "admitted") {
      throw unavailable("evidence-unavailable", "as-of-frontier-incomplete");
    }
    const witness = view.substrate.witness(ref);
    if (witness === undefined) throw unavailable("evidence-unavailable", "as-of-frontier-missing");
    closure.add(ref);
    for (const cause of witness.core.causes) pending.push(cause);
  }
  const membership = view.feedEvents.get(selection.feed) ?? new Set();
  const refs = [...closure].filter((ref) => membership.has(ref));
  sourceCompleteRefs(view, refs);
  return refs;
}","after":"function sourceAsOfRefs(view, selection) {
  const closure = new Set();
  const pending = [...selection.frontier];
  while (pending.length > 0) {
    const ref = pending.pop();
    if (closure.has(ref)) continue;
    if (view.substrate.witnessState(ref) !== "admitted") {
      throw unavailable("evidence-unavailable", "as-of-frontier-incomplete");
    }
    const witness = view.substrate.witness(ref);
    if (witness === undefined) throw unavailable("evidence-unavailable", "as-of-frontier-missing");
    closure.add(ref);
    for (const cause of witness.core.causes) pending.push(cause);
  }
  const membership = view.feedEvents.get(selection.feed) ?? new Set();
  const refs = [...closure].filter((ref) => membership.has(ref));
  sourceCompleteRefs(view, refs);
  return Object.freeze({ refs, requiredRefs: Object.freeze([...closure]) });
}"},{"before":"  if (selection.kind === "as-of") {
    refs = sourceAsOfRefs(view, selection);
  } else {
    const selected = new Set();
    for (const feed of sourceSelectionFeeds(view, selection)) {
      for (const ref of view.feedEvents.get(feed) ?? []) selected.add(ref);
    }
    refs = [...selected];
    sourceCompleteRefs(view, refs);
  }
  return sourceOrderedEnvelopes(view, refs);","after":"  let requiredRefs;
  if (selection.kind === "as-of") {
    const asOf = sourceAsOfRefs(view, selection);
    refs = asOf.refs;
    requiredRefs = asOf.requiredRefs;
  } else {
    const selected = new Set();
    for (const feed of sourceSelectionFeeds(view, selection)) {
      for (const ref of view.feedEvents.get(feed) ?? []) selected.add(ref);
    }
    refs = [...selected];
    sourceCompleteRefs(view, refs);
  }
  return sourceOrderedEnvelopes(view, refs, requiredRefs ?? refs);"},{"before":"    representationBytes += Buffer.byteLength(`${canonicalJson(envelope.statement)}\\n`, "utf8");","after":"    representationBytes += Buffer.byteLength(`${canonicalJson(envelope.statement)}\n`, "utf8");"}],"clauses":["F-S05","F-S19"]}]}
